def transform(grid):
    h,w=len(grid),len(grid[0]); bh,bw=3,3
    out=[]
    for r in range(0,h,bh):
        row=[]
        for c in range(0,w,bw):
            colors={grid[i][j] for i in range(r,min(r+bh,h)) for j in range(c,min(c+bw,w)) if grid[i][j] not in (0,5)}
            row.append(next(iter(colors)) if colors else 0)
        out.append(row)
    return out
